-- =====================================================================
-- ms-reservations | Seed data for RESERVATIONS
-- Idempotent: a row is only inserted if a reservation with the same
-- (UNIT_ID, GUEST_ID, START_DATE) does not exist yet.
--
-- ID is generated by the DB (GenerationType.IDENTITY).
-- CREATED_AT / UPDATED_AT are set explicitly because @PrePersist does
-- not run for plain SQL inserts (and CREATED_AT is NOT NULL).
--
-- UNIT_ID values refer to the ms-catalog seed, assuming it ran first on
-- an empty UNITS table (IDs 1..12 in insert order):
--   1 Habitación Cordillera (45.000)     7  Apartamento Bellas Artes (70.000)
--   2 Habitación Barrio Italia (38.000)  8  Apartamento Costanera (110.000)
--   3 Habitación Cerro Alegre (42.000)   9  Apartamento Playa Reñaca (85.000)
--   4 Suite Presidencial Andes (180.000) 10 Cabaña Lago Villarrica (120.000)
--   5 Suite Ejecutiva Las Condes (95.000) 11 Cabaña Valle Nevado (135.000)
--   6 Suite Vista al Mar (150.000)       12 Cabaña Cajón del Maipo (80.000)
-- TOTAL_AMOUNT = price per night * number of nights (CLP).
-- =====================================================================

-- ---------- CHECKOUT (past stays) ----------
INSERT INTO RESERVATIONS (UNIT_ID, GUEST_ID, GUEST_EMAIL, START_DATE, END_DATE, TOTAL_AMOUNT, STATUS, CREATED_AT, UPDATED_AT)
SELECT 1, 'guest-001', 'camila.rojas@example.com', DATE '2026-09-10', DATE '2026-09-13', 135000.00, 'CHECKOUT', TIMESTAMP '2026-08-25 10:15:00', TIMESTAMP '2026-09-13 11:00:00'
WHERE NOT EXISTS (SELECT 1 FROM RESERVATIONS WHERE UNIT_ID = 1 AND GUEST_ID = 'guest-001' AND START_DATE = DATE '2026-09-10');

INSERT INTO RESERVATIONS (UNIT_ID, GUEST_ID, GUEST_EMAIL, START_DATE, END_DATE, TOTAL_AMOUNT, STATUS, CREATED_AT, UPDATED_AT)
SELECT 2, 'guest-008', 'diego.fuentes@example.com', DATE '2026-09-01', DATE '2026-09-04', 114000.00, 'CHECKOUT', TIMESTAMP '2026-08-10 16:40:00', TIMESTAMP '2026-09-04 10:30:00'
WHERE NOT EXISTS (SELECT 1 FROM RESERVATIONS WHERE UNIT_ID = 2 AND GUEST_ID = 'guest-008' AND START_DATE = DATE '2026-09-01');

